CREATE SET TABLE MDP01_META.META_ETL_JOB_TEMPLATE ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      TEMPLATE_ID INTEGER NOT NULL GENERATED ALWAYS AS IDENTITY           (START WITH 1             INCREMENT BY 1             MINVALUE -2147483647             MAXVALUE 2147483647             NO CYCLE),      TEMPLATE_NAME VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      TEMPLATE_CODE VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      SOURCE_LAYER_ID INTEGER,      TARGET_LAYER_ID INTEGER,      JOB_TYPE VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      DEFAULT_PRIMARY_KEY_COLUMNS VARCHAR(500) CHARACTER SET LATIN NOT CASESPECIFIC,      DEFAULT_HASH_COLUMNS VARCHAR(2000) CHARACTER SET LATIN NOT CASESPECIFIC,      DEFAULT_INCREMENTAL_COLUMN VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC,      DEFAULT_VALID_FROM_COLUMN VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'GUELTIG_VON',      DEFAULT_VALID_TO_COLUMN VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'GUELTIG_BIS',      DEFAULT_IS_CURRENT_COLUMN VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'IST_AKTUELL',      DEFAULT_PARALLELISM INTEGER DEFAULT 1 ,      DEFAULT_BATCH_SIZE INTEGER,      DEFAULT_RETRY_COUNT INTEGER DEFAULT 3 ,      DEFAULT_TIMEOUT_SECONDS INTEGER DEFAULT 3600 ,      CATEGORY VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC,      TAGS VARCHAR(500) CHARACTER SET LATIN NOT CASESPECIFIC,      BESCHREIBUNG VARCHAR(2000) CHARACTER SET LATIN NOT CASESPECIFIC,      USAGE_NOTES VARCHAR(4000) CHARACTER SET LATIN NOT CASESPECIFIC,      IS_ACTIVE CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC CHECK ( IS_ACTIVE  IN ('Y','N') ) DEFAULT 'Y',      CREATED_BY VARCHAR(200) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT USER ,      CREATE_TIMESTAMP TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),      MODIFIED_BY VARCHAR(200) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT USER ,      LAST_ALTER_TIMESTAMP TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),      USE_SK CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'N')PRIMARY INDEX ( TEMPLATE_ID )UNIQUE INDEX ( TEMPLATE_CODE );